package com.lee.spa.commerce;

import com.baomidou.mybatisplus.core.toolkit.IdWorker;
import com.lee.spa.auth.AuthContext;
import com.lee.spa.auth.AuthException;
import com.lee.spa.common.exception.BusinessException;
import lombok.RequiredArgsConstructor;
import org.springframework.core.env.Environment;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;

@Service @RequiredArgsConstructor
public class LoyaltyService {
 private final JdbcTemplate jdbc;private final Environment env;
 private static final ZoneId ZONE=ZoneId.of("Asia/Shanghai");
 private long number(Object value){return ((Number)value).longValue();}
 private void lock(long user){jdbc.update("INSERT INTO spa_loyalty_guard(user_id) VALUES(?) ON DUPLICATE KEY UPDATE user_id=user_id",user);jdbc.queryForList("SELECT user_id FROM spa_loyalty_guard WHERE user_id=? FOR UPDATE",user);}
 public boolean mockEnabled(){var p=Arrays.asList(env.getActiveProfiles());return (p.contains("local")||p.contains("test"))&&!p.contains("prod")&&!p.contains("production")&&env.getProperty("spa.payment.mock-enabled",Boolean.class,false);}
 private void requireMock(){if(!mockEnabled())throw new AuthException(403,"测试钱包仅在显式启用的本地或测试环境开放");}
 private long points(long user){String suffix=org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()?" FOR UPDATE":"";return jdbc.queryForList("SELECT points FROM spa_points_entry WHERE user_id=?"+suffix,Long.class,user).stream().mapToLong(Long::longValue).sum()+jdbc.queryForList("SELECT points FROM spa_points_adjustment WHERE user_id=?"+suffix,Long.class,user).stream().mapToLong(Long::longValue).sum();}
 private BigDecimal balance(long user){String suffix=org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive()?" FOR UPDATE":"";var rows=jdbc.queryForList("SELECT balance FROM spa_mock_wallet WHERE user_id=?"+suffix,user);return rows.isEmpty()?BigDecimal.ZERO:(BigDecimal)rows.get(0).get("balance");}
 public Map<String,Object> summary(){long user=AuthContext.requireUserId();long points=points(user);long earned=jdbc.queryForObject("SELECT COALESCE(SUM(points),0) FROM spa_points_entry WHERE user_id=?",Long.class,user);return Map.of("points",points,"memberLevel",earned>=3000?"GOLD":earned>=1000?"SILVER":"STANDARD","walletBalance",balance(user),"walletMode","DEVELOPMENT_SIMULATION","mockWalletEnabled",mockEnabled());}
 public Map<String,Object> coupons(){long user=AuthContext.requireUserId();var templates=jdbc.queryForList("SELECT CAST(id AS CHAR) id,title,discount_amount discountAmount,min_amount minAmount,DATE_FORMAT(expires_at,'%Y-%m-%dT%H:%i:%s') expiresAt,remaining FROM spa_coupon_template WHERE active=1 AND expires_at>? AND remaining>0 ORDER BY created_at DESC",LocalDateTime.now(ZONE));var owned=jdbc.queryForList("SELECT CAST(c.id AS CHAR) id,t.title,t.discount_amount discountAmount,t.min_amount minAmount,DATE_FORMAT(t.expires_at,'%Y-%m-%dT%H:%i:%s') expiresAt,CASE WHEN c.status='AVAILABLE' AND t.expires_at<=? THEN 'EXPIRED' ELSE c.status END status,CAST(c.order_id AS CHAR) orderId FROM spa_user_coupon c JOIN spa_coupon_template t ON t.id=c.template_id WHERE c.user_id=? ORDER BY c.created_at DESC",LocalDateTime.now(ZONE),user);return Map.of("templates",templates,"owned",owned);}
 @Transactional public void claim(long template){long user=AuthContext.requireUserId();lock(user);var templates=jdbc.queryForList("SELECT * FROM spa_coupon_template WHERE id=? AND active=1 AND remaining>0 AND expires_at>? FOR UPDATE",template,LocalDateTime.now(ZONE));if(templates.isEmpty())throw new BusinessException("优惠券已领完或已过期");if(jdbc.queryForObject("SELECT COUNT(*) FROM spa_user_coupon WHERE user_id=? AND template_id=?",Long.class,user,template)>0)throw new BusinessException("每人限领一次");jdbc.update("INSERT INTO spa_user_coupon(id,user_id,template_id) VALUES(?,?,?)",IdWorker.getId(),user,template);jdbc.update("UPDATE spa_coupon_template SET remaining=remaining-1 WHERE id=?",template);}
 public record Template(String title,BigDecimal discountAmount,BigDecimal minAmount,LocalDateTime expiresAt,Integer remaining){ }
 @Transactional public void createTemplate(Template input){AuthContext.requireRole("ADMIN");if(input.title()==null||input.title().isBlank()||input.title().length()>100||input.discountAmount()==null||input.discountAmount().signum()<=0||input.discountAmount().scale()>2||input.minAmount()==null||input.minAmount().signum()<0||input.minAmount().scale()>2||input.expiresAt()==null||!input.expiresAt().isAfter(LocalDateTime.now(ZONE))||input.remaining()==null||input.remaining()<1||input.remaining()>100000)throw new BusinessException("优惠券配置无效");jdbc.update("INSERT INTO spa_coupon_template(id,title,discount_amount,min_amount,expires_at,remaining) VALUES(?,?,?,?,?,?)",IdWorker.getId(),input.title(),input.discountAmount(),input.minAmount(),input.expiresAt(),input.remaining());}
 public List<Map<String,Object>> templates(){AuthContext.requireRole("ADMIN");return jdbc.queryForList("SELECT CAST(id AS CHAR) id,title,discount_amount discountAmount,min_amount minAmount,DATE_FORMAT(expires_at,'%Y-%m-%dT%H:%i:%s') expiresAt,remaining,active FROM spa_coupon_template ORDER BY created_at DESC");}
 @Transactional public void setTemplateActive(long id,boolean active){AuthContext.requireRole("ADMIN");if(jdbc.update("UPDATE spa_coupon_template SET active=? WHERE id=?",active?1:0,id)!=1)throw new BusinessException("优惠券不存在");}
 // Called only after the business-day and order row locks, inside the caller's transaction.
 public void apply(Map<String,Object> order,Long couponId,int points){long user=number(order.get("user_id")),id=number(order.get("id"));lock(user);if(!"WAITING_PAYMENT".equals(order.get("status")))throw new BusinessException("仅待支付订单可以使用优惠");if(points<0||points>1000000)throw new BusinessException("积分参数无效");release(order,false);BigDecimal original=jdbc.queryForObject("SELECT amount FROM appointment WHERE id=?",BigDecimal.class,order.get("appointment_id"));BigDecimal discount=BigDecimal.ZERO;
  if(couponId!=null){var rows=jdbc.queryForList("SELECT c.id,t.discount_amount,t.min_amount FROM spa_user_coupon c JOIN spa_coupon_template t ON t.id=c.template_id WHERE c.id=? AND c.user_id=? AND c.status='AVAILABLE' AND t.expires_at>? FOR UPDATE",couponId,user,LocalDateTime.now(ZONE));if(rows.isEmpty())throw new BusinessException("优惠券不可用或已过期");var coupon=rows.get(0);if(original.compareTo((BigDecimal)coupon.get("min_amount"))<0)throw new BusinessException("订单金额未达到优惠券门槛");discount=((BigDecimal)coupon.get("discount_amount")).min(original);jdbc.update("UPDATE spa_user_coupon SET status='RESERVED',order_id=? WHERE id=?",id,couponId);}
  BigDecimal redemption=BigDecimal.valueOf(points,2);if(points>points(user)||redemption.compareTo(original.subtract(discount))>0)throw new BusinessException("可用积分或订单金额不足");
  jdbc.update("INSERT INTO spa_order_benefit(order_id,user_id,coupon_id,points_used,original_amount,status) VALUES(?,?,?,?,?,'RESERVED') ON DUPLICATE KEY UPDATE coupon_id=VALUES(coupon_id),points_used=VALUES(points_used),original_amount=VALUES(original_amount),status='RESERVED'",id,user,couponId,points,original);
  jdbc.update("INSERT INTO spa_points_adjustment(id,user_id,order_id,points,kind) VALUES(?,?,?,?,'RESERVE') ON DUPLICATE KEY UPDATE points=VALUES(points)",IdWorker.getId(),user,id,-points);
  jdbc.update("INSERT INTO spa_points_adjustment(id,user_id,order_id,points,kind) VALUES(?,?,?,0,'RELEASE') ON DUPLICATE KEY UPDATE points=0",IdWorker.getId(),user,id);
  jdbc.update("UPDATE spa_order SET amount=? WHERE id=?",original.subtract(discount).subtract(redemption),id);
 }
 public void consume(Map<String,Object> order,String channel){long user=number(order.get("user_id")),id=number(order.get("id"));lock(user);if(!jdbc.queryForList("SELECT c.id FROM spa_user_coupon c JOIN spa_coupon_template t ON t.id=c.template_id WHERE c.order_id=? AND c.status='RESERVED' AND t.expires_at<=? FOR UPDATE",id,LocalDateTime.now(ZONE)).isEmpty())throw new BusinessException("优惠券已过期，请重新选择优惠");if(channel.equals("MOCK_WALLET")){requireMock();walletEntry(user,"pay:"+id,((BigDecimal)order.get("amount")).negate(),"PAYMENT");}jdbc.update("UPDATE spa_user_coupon SET status='USED' WHERE order_id=? AND status='RESERVED'",id);jdbc.update("UPDATE spa_order_benefit SET status='USED' WHERE order_id=? AND status='RESERVED'",id);}
 public void release(Map<String,Object> order,boolean refundWallet){long user=number(order.get("user_id")),id=number(order.get("id"));lock(user);var rows=jdbc.queryForList("SELECT * FROM spa_order_benefit WHERE order_id=? AND status IN ('RESERVED','USED') FOR UPDATE",id);if(!rows.isEmpty()){int used=((Number)rows.get(0).get("points_used")).intValue();jdbc.update("INSERT INTO spa_points_adjustment(id,user_id,order_id,points,kind) VALUES(?,?,?,?,'RELEASE') ON DUPLICATE KEY UPDATE points=VALUES(points)",IdWorker.getId(),user,id,used);jdbc.update("UPDATE spa_user_coupon SET status='AVAILABLE',order_id=NULL WHERE order_id=?",id);jdbc.update("UPDATE spa_order_benefit SET status='RELEASED' WHERE order_id=?",id);}if(refundWallet&&"MOCK_WALLET".equals(order.get("payment_channel")))walletEntry(user,"refund:"+id,(BigDecimal)order.get("amount"),"REFUND");}
 @Transactional public Map<String,Object> topup(BigDecimal amount,String request){requireMock();long user=AuthContext.requireUserId();if(amount==null||amount.signum()<=0||amount.scale()>2||amount.compareTo(new BigDecimal("10000"))>0||request==null||!request.matches("[A-Za-z0-9_-]{8,64}"))throw new BusinessException("测试充值金额或请求标识无效");lock(user);walletEntry(user,"topup:"+request,amount,"TEST_TOPUP");return summary();}
 private void walletEntry(long user,String request,BigDecimal amount,String kind){var existing=jdbc.queryForList("SELECT amount,kind FROM spa_mock_wallet_ledger WHERE user_id=? AND request_id=? FOR UPDATE",user,request);if(!existing.isEmpty()){if(((BigDecimal)existing.get(0).get("amount")).compareTo(amount)!=0||!kind.equals(existing.get(0).get("kind")))throw new BusinessException("请求标识已用于不同金额");return;}jdbc.update("INSERT INTO spa_mock_wallet(user_id,balance) VALUES(?,0) ON DUPLICATE KEY UPDATE user_id=user_id",user);BigDecimal next=balance(user).add(amount);if(next.signum()<0)throw new BusinessException("测试钱包余额不足");jdbc.update("UPDATE spa_mock_wallet SET balance=? WHERE user_id=?",next,user);jdbc.update("INSERT INTO spa_mock_wallet_ledger(id,user_id,request_id,amount,balance_after,kind) VALUES(?,?,?,?,?,?)",IdWorker.getId(),user,request,amount,next,kind);}
 public List<Map<String,Object>> ledger(){AuthContext.requireRole("ADMIN");return jdbc.queryForList("SELECT CAST(id AS CHAR) id,amount,balance_after balanceAfter,kind,request_id requestId,DATE_FORMAT(created_at,'%Y-%m-%dT%H:%i:%s') createdAt FROM spa_mock_wallet_ledger WHERE user_id=? ORDER BY created_at DESC,id DESC LIMIT 200",AuthContext.requireUserId());}
}
